    @mcp.tool()
    def contrarian_brief(condition_id: str) -> dict:
        """
        Summarize the market's causal/contrarian dossier.

        Use this before hidden-gem review. It answers: who matters, what mechanism
        matters, what looks weird, what paths exist, and how our thesis could fail.
        """
        _ensure_db()
        with db.connect() as conn:
            market = conn.execute(
                "SELECT question, vertical, end_date FROM markets WHERE condition_id = ?",
                (condition_id,),
            ).fetchone()
            if not market:
                return {"error": f"market {condition_id} not found"}
            actors = conn.execute("""
                SELECT actor_name, actor_type, role, incentives, constraints,
                       likely_action, influence_score, visibility_score
                FROM actor_maps
                WHERE condition_id = ?
                ORDER BY influence_score DESC, created_at DESC LIMIT 20
            """, (condition_id,)).fetchall()
            factors = conn.execute("""
                SELECT factor_name, mechanism, direction, importance, uncertainty,
                       observable_signal, current_state, next_check_at
                FROM causal_factors
                WHERE condition_id = ?
                ORDER BY importance DESC, created_at DESC LIMIT 20
            """, (condition_id,)).fetchall()
            anomalies = conn.execute("""
                SELECT anomaly_type, observation, why_it_matters, implied_direction,
                       severity, confidence, status, source_url
                FROM anomalies
                WHERE condition_id = ?
                ORDER BY severity DESC, created_at DESC LIMIT 20
            """, (condition_id,)).fetchall()
            scenarios = conn.execute("""
                SELECT scenario_name, path, probability, outcome_side,
                       key_assumptions, breakpoints, early_warning_signals
                FROM scenario_trees
                WHERE condition_id = ?
                ORDER BY probability DESC, created_at DESC LIMIT 20
            """, (condition_id,)).fetchall()
            premortems = conn.execute("""
                SELECT thesis, failure_mode, disconfirming_signal,
                       probability_if_wrong, mitigation, severity
                FROM premortems
                WHERE condition_id = ?
                ORDER BY severity DESC, created_at DESC LIMIT 20
            """, (condition_id,)).fetchall()
        scenario_sum = sum(float(r["probability"]) for r in scenarios)
        open_anomalies = [r for r in anomalies if r["status"] == "open"]
        return {
            "condition_id": condition_id,
            "question": market["question"],
            "vertical": market["vertical"],
            "end_date": market["end_date"],
            "actor_count": len(actors),
            "causal_factor_count": len(factors),
            "open_anomaly_count": len(open_anomalies),
            "scenario_count": len(scenarios),
            "scenario_probability_sum": round(scenario_sum, 4),
            "premortem_count": len(premortems),
            "actors": [dict(r) for r in actors],
            "causal_factors": [dict(r) for r in factors],
            "anomalies": [dict(r) for r in anomalies],
            "scenarios": [dict(r) for r in scenarios],
            "premortems": [dict(r) for r in premortems],
        }


